  })

  test("turning the aim counts; holding still with the same aim does not", () => {
    const s = setup()
    for (let k = 0; k < 6; k++) s.advance(IDLE_KICK_MS / 3, { aim: k * 0.5 })
    expect(s.closed()).toBe(0)
