// Writes shared/build.gen.ts: a hash of everything in shared/ (protocol and simulation). The client sends it in its
// hello; a server built from different shared code tells the client to reload, so old tabs never talk an old protocol.
import { createHash } from "node:crypto"
import { readFileSync, readdirSync, statSync, writeFileSync } from "node:fs"
import { join, relative } from "node:path"

const root = join(import.meta.dir, "..")
const out = join(root, "shared/build.gen.ts")
const files: string[] = []
const walk = (dir: string) => {
  for (const name of readdirSync(dir).sort()) {
    const p = join(dir, name)
    if (p === out) continue
    if (statSync(p).isDirectory()) walk(p)
    else if (p.endsWith(".ts")) files.push(p)
  }
}
walk(join(root, "shared"))
const h = createHash("sha256")
for (const f of files) h.update(relative(root, f)).update("\0").update(readFileSync(f)).update("\0")
const id = h.digest("hex").slice(0, 12)
writeFileSync(out, `// Generated by scripts/build-id.ts. Do not edit.\nexport const BUILD = "${id}"\n`)
console.log(`build ${id}`)

import type { Lobby } from "./lobby"
import type { Room } from "./room"

export interface Env {
  ROOM: DurableObjectNamespace<Room>
  LOBBY: DurableObjectNamespace<Lobby>
  ASSETS?: Fetcher
}

export const lobbyOf = (env: Env) => env.LOBBY.get(env.LOBBY.idFromName("lobby"))

// Runs the Worker (rooms) and the Vite client together. Vite proxies /ws and /api to the Worker.
await Bun.spawn(["bun", "scripts/build-id.ts"], { stdio: ["inherit", "inherit", "inherit"] }).exited
const procs = [
  Bun.spawn(["bunx", "wrangler", "dev", "--port", "8788"], { stdio: ["inherit", "inherit", "inherit"] }),
  Bun.spawn(["bunx", "vite", "--host", "0.0.0.0", "--port", "5191", "--strictPort"], { stdio: ["inherit", "inherit", "inherit"] }),
]

let stopping = false
function stop(code = 0) {
  if (stopping) return
  stopping = true
  for (const p of procs) p.kill()
  process.exit(code)
}

process.on("SIGINT", () => stop(0))
process.on("SIGTERM", () => stop(0))
process.on("exit", () => {
  for (const p of procs) p.kill()
})
await Promise.race(procs.map((p) => p.exited.then((code) => code)))
stop(1)

import { DurableObject } from "cloudflare:workers"
import type { Env } from "./env"
import { Matchmaker, type RoomEntry, type RoomReport } from "./matchmaking"

/**
 * Singleton matchmaker. Room reports are kept in storage too, so a Lobby that was evicted or restarted still knows
 * every live room at once instead of waiting for their next heartbeat.
 */
export class Lobby extends DurableObject<Env> {
  private mm = new Matchmaker()

  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env)
    ctx.blockConcurrencyWhile(async () => {
      const saved = await ctx.storage.get<RoomEntry[]>("rooms")
      for (const r of saved ?? []) this.mm.rooms.set(r.code, r)
    })
  }

  async report(r: RoomReport) {
    this.mm.report(r, Date.now())
    await this.ctx.storage.put("rooms", [...this.mm.rooms.values()])
  }

  quick() {
    return this.mm.quick(Date.now())
  }

  create() {
    return this.mm.create(Date.now())
  }

  stats() {
    return this.mm.stats(Date.now())
  }
}
